beforeSaveCustomScript:
if (transactionDate == null) {
    transactionDate = datetime\today();
}
if (amount == null) {
    amount = 0;
}
if (entryType == 'Income') {
    amountIn = amount;
    amountOut = 0;
} else if (entryType == 'Expense') {
    amountOut = amount;
    amountIn = 0;
}
name = string\concatenate(transactionDate, ' — ', description);
